      "title": "ScholarCatalyst: A Benchmark for Retrieving Papers That Inspire New Research",
      "url": "https://arxiv.org/abs/2610.02202v1",
      "pdfUrl": "https://arxiv.org/pdf/2610.02202v1",
      "source": "arXiv",
      "points": 0,
